function nflBadgeFacts(c) {
  const t = careerTotals(c);
  let sacks = 0, picks = 0, tackles = 0, fgMade = 0;
  for (const s of c.seasons) {
    sacks += s.sacks ?? 0;
    picks += s.picks ?? 0;
    tackles += s.tackles ?? 0;
    fgMade += s.fgMade ?? 0;
  }
  return {
    pos: c.pos,
    seasons: c.seasons.map((s) => ({
      games: s.games,
      awards: s.awards ?? [],
      teamResult: s.teamResult,
      passYds: s.passYds,
      rushYds: s.rushYds,
      sacks: s.sacks
    })),
    rings: c.rings,
    mvps: c.mvps,
    allPros: c.allPros,
    totals: {
      passYds: t.passYds,
      rushYds: t.rushYds,
      recYds: t.recYds,
      recTd: t.recTd,
      sacks: Math.round(sacks * 10) / 10,
      picks,
      tackles,
      fgMade
    },
    /* Round 470: what a full season is, moved onto the facts so the iron man
       badge reads the same field in all four American careers. Round 1104:
       the whole schedule is the length of THAT season (16 games before
       2021, 17 since), so a full 2005 season counts as a full one. */
    fullSeasons: c.seasons.filter((s) => s.games >= nflSeasonLength(s.year)).length,
    wealth: Math.round(((c.netWorth ?? 0) + nflMoneyWealth(c)) * 100) / 100,
    retired: c.retired,
    hof: c.retired && legacyOf(c).hof,
    rival: c.rival ? { retired: c.rival.retired, myYears: c.rival.myYears, hisYears: c.rival.hisYears } : null
  };
}
function nflEarnedBadges(c) {
  return earnedBadges(NFL_BADGES, nflBadgeFacts(c));
}
function nflFollowers(c) {
  return followersFromFanbase({
    fanbase: c.fanbase,
    seasons: c.seasons.length,
    rings: c.rings,
    awards: c.mvps + c.allPros
  });
}
function nflFanComments(c) {
  return fanComments("nfl", {
    pos: c.pos,
    standing: c.fanbase,
    followers: fmtFollowers(nflFollowers(c))
  });
}
function nflHeadlinesFor(c, line) {
  return nflSeasonHeadlines({
    name: c.name,
    team: teamLabelOf(line.team, c.eraId),
    pos: c.pos,
    line,
    /* A starter's games are the season's length (Round 1104: 16 before
       2021, 17 since) less what injury took, so the gap is the injury. A backup's games are spot duty by design (Round 182), so the
       gap says nothing about his health and is not reported as one. */
    missed: line.teamResult === "SUSPENDED" || c.role === "backup" ? 0 : Math.max(0, nflSeasonLength(line.year) - line.games),
    role: c.role
  });
}

