var L5 = (c) => c;
var flag7 = (c, k) => (L5(c).lifeFlags || {})[k] || 0;
var setFlag7 = (c, k, v) => {
  L5(c).lifeFlags = { ...L5(c).lifeFlags || {}, [k]: v };
};
var bump2 = (c, k) => setFlag7(c, k, flag7(c, k) + 1);
var clamp18 = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
var mor3 = (c, d) => {
  c.morale = clamp18(c.morale + d, 0, 100);
};
var fan3 = (c, d) => {
  c.fanbase = clamp18(c.fanbase + d, 0, 100);
};
var hp3 = (c, d) => {
  c.health = clamp18(c.health + d, 0, 100);
};
var rate3 = (c, d) => {
  c.ovr = clamp18(Math.min(c.pot + 1, c.ovr + d), 50, 99);
};
var bank6 = (c, d) => {
  const s = L5(c);
  s.netWorth = Math.round(((s.netWorth ?? 0) + d) * 100) / 100;
  return s.netWorth;
};
var paid3 = (c, m) => {
  c.earnings = Math.round((c.earnings + m) * 100) / 100;
  return bank6(c, m);
};
var own5 = (c, item) => {
  const s = L5(c);
  s.purchased = [...s.purchased ?? [], item];
};
