// src/lib/mlbCareerMoney.ts
init_careerMoney();
var clamp21 = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
var MLB_MONEY = {
  currency: "$",
  seedOf: (c) => seedFromName(c.name, c.seasons?.length ?? 0),
  yearOf: (c) => c.seasons.length > 0 ? c.seasons[c.seasons.length - 1].year : c.year,
  billOf: (c) => c.yearlyCosts ?? 0,
  shame: (c) => {
    c.fanbase = clamp21(c.fanbase - 2, 0, 100);
  },
  words: {
    cards: {
      ledger: "Cards in the clubhouse",
      crew: "the guys",
      crewCap: "The guys",
      where: "in the clubhouse",
      thatPlace: "in that clubhouse card game",
      next: "Next homestand."
    },
    arcade: { ledger: "Won the phone quiz", name: "the ball quiz" }
  }
};
function mlbMoneyWealth(c) {
  return moneyWealth(c, MLB_MONEY);
}
function mlbMoneySeasonTick(c) {
  return moneySeasonTick(c, MLB_MONEY.yearOf(c), MLB_MONEY);
}
function mlbMoneyAct(c, action) {
  return moneyAct(c, action, MLB_MONEY);
}

