var MLB_INBOX = {
  pool: MLB_INBOX_POOL,
  moodOf: (c) => c.karma ?? 50,
  setMood: (c, v) => {
    c.karma = v;
  },
  addPopularity: (c, delta) => {
    c.fanbase = clamp22(c.fanbase + delta, 0, 100);
  },
  addCash: (c, amount) => {
    c.netWorth = Math.round(((c.netWorth ?? 0) + amount) * 10) / 10;
  },
  ageOf: (c) => c.age,
  yearOf: (c) => c.seasons.length > 0 ? c.seasons[c.seasons.length - 1].year : c.year,
  maxInbox: 6,
  wantPerSeason: 3,
  calendar: MLB_CALENDAR
};
function mlbSeasonBeats(c) {
  const line = c.seasons[c.seasons.length - 1];
  if (!line || line.teamResult === "SUSPENDED") return ["offseason"];
  const beats = ["spring", "allstar", "deadline", "september"];
  if ((line.poGames ?? 0) > 0) beats.push("october");
  beats.push("offseason");
  const service = c.seasons.length;
  if (!c.retired && service >= 3 && service <= 5 && c.contractYears >= 1) beats.push("arbitration");
  if (!c.retired && c.contractYears <= 0) beats.push("freeagency");
  return beats;
}
function receiveMlbInboxTexts(c, goesOn = true, rng) {
  return receiveCalendarInboxTexts(c, "pro", MLB_INBOX, rng ?? inboxStream(c, "season"), mlbSeasonBeats(c), goesOn && !c.retired);
}
function mlbDraftNightInbox(c, rng) {
  return deliverInboxTexts(c, "pro", MLB_INBOX, rng ?? inboxStream(c, "draft"), ["draft"]);
}
function mlbUnreadInboxCount(c) {
  return unreadInboxCount(c);
}
function answerMlbInboxMessage(c, msgId, choiceIdx) {
  return answerInboxMessage(c, msgId, choiceIdx, MLB_INBOX);
}

