function getMlbSpendItem(id) {
  return MLB_SPEND_ITEMS.find((i) => i.id === id);
}
function buyMlbItem(c, itemId) {
  const item = getMlbSpendItem(itemId);
  if (!item) return null;
  const owned = c.purchased ?? [];
  if (item.oneTime && owned.includes(itemId)) return null;
  const net = c.netWorth ?? Math.round(c.earnings * 0.45 * 10) / 10;
  if (item.minNetWorth && net < item.minNetWorth) return null;
  if (item.minFanbase && c.fanbase < item.minFanbase) return null;
  if (item.requiresDirty && (c.dirtyMoney ?? 0) <= 0) return null;
  if (item.cost > net) return null;
  const s = { ...c, purchased: [...owned, itemId] };
  s.netWorth = Math.round((net - item.cost) * 10) / 10;
  if (item.yearly) s.yearlyCosts = Math.round(((s.yearlyCosts ?? 0) + item.yearly) * 100) / 100;
  let log = `Bought ${item.name}.`;
  switch (itemId) {
    case "hometown_court":
      s.fanbase = Math.min(100, s.fanbase + 12);
      log = "You rebuilt the courts you grew up on. The whole neighborhood came out for the reopening.";
      break;
    case "youth_academy_mlb":
      s.fanbase = Math.min(100, s.fanbase + 8);
      log = "Your academy opened with 120 kids on day one.";
      break;
    case "team_stake":
      s.fanbase = Math.min(100, s.fanbase + 10);
      log = "You own a piece of a franchise now. The other owners are still deciding how they feel about that.";
      break;
    case "sleep_mlb":
      s.health = Math.min(100, s.health + 8);
      log = "Turns out it was mostly sleep the whole time. Health +8.";
      break;
    case "biomech_mlb":
      s.ovr = raiseWithinPotential(s.ovr, s.pot, 2);
      log = `They rebuilt how you land and everything got easier. ${ratingRaiseNote(c.ovr, s.ovr, 2)}`;
      break;
    case "psych_mlb":
      s.morale = Math.min(100, s.morale + 8);
      log = "Best hire you ever made and the one you almost skipped. Morale +8.";
      break;
    case "mom_house_mlb":
      s.morale = Math.min(100, s.morale + 15);
      log = "You handed your mother the keys and she did not say a word for a full minute. Morale +15.";
      break;
    case "siblings_mlb":
      s.morale = Math.min(100, s.morale + 10);
      log = "Every sibling, all four years, paid in full. Morale +10.";
      break;
    case "album":
      s.fanbase = Math.min(100, s.fanbase + 10);
      log = "The album has four million streams and the locker room has never let it go. Fanbase +10.";
      break;
    case "signature_shoe":
      s.fanbase = Math.min(100, s.fanbase + 12);
      log = "Your silhouette is on a shoe in every mall in the country. Fanbase +12.";
      break;
    case "foundation_mlb":
      s.fanbase = Math.min(100, s.fanbase + 10);
      log = "The foundation launched with a block party and a scholarship fund. Fanbase +10.";
      break;
    case "mshady_laundromats": {
      const w = Math.min(2, c.dirtyMoney ?? 0);
      s.dirtyMoney = Math.max(0, Math.round(((s.dirtyMoney ?? 0) - 2) * 10) / 10);
      s.netWorth = Math.round((s.netWorth + w) * 10) / 10;
      log = "Two million went in dirty and came out as a very busy laundromat chain.";
      break;
    }
    case "mshady_barbers": {
      const w = Math.min(1.5, c.dirtyMoney ?? 0);
      s.dirtyMoney = Math.max(0, Math.round(((s.dirtyMoney ?? 0) - 1.5) * 10) / 10);
      s.netWorth = Math.round((s.netWorth + w) * 10) / 10;
      log = "Nine chairs, three customers, and a ledger that balances beautifully.";
      break;
    }
    case "mshady_club": {
      const w = Math.min(4, c.dirtyMoney ?? 0);
      s.dirtyMoney = Math.max(0, Math.round(((s.dirtyMoney ?? 0) - 4) * 10) / 10);
      s.netWorth = Math.round((s.netWorth + w) * 10) / 10;
      s.heat = Math.min(100, (s.heat ?? 0) + 3);
      log = "The club opened. Four million cleaned and a line around the block.";
      break;
    }
    case "mshady_fixer":
      s.heat = Math.max(0, (s.heat ?? 0) - 8);
      log = "You have a guy now. Heat -8, and you genuinely do not want to know how.";
      break;
    case "mshady_offshore":
      s.heat = Math.min(100, (s.heat ?? 0) + 6);
      log = "The account is open. An island, a bank, and a form nobody will ever file. Heat +6.";
      break;
    default:
      break;
  }
  return { state: s, log };
}

