  roleBadge: (c) => c.pos === "RP" ? "\u2B50 Bullpen arm" : c.role === "backup" ? c.pos === "SP" ? "\u{1FA91} Spot starter" : "\u{1FA91} Bench bat" : c.pos === "SP" ? "\u2B50 In the rotation" : "\u2B50 Everyday",
