// src/lib/nhlCareerWaivers.ts
var currentAgreement = (c) => nhlEraById(c.eraId).id === "now" || c.year >= 2013;
var gamesLimit = (c) => c.pos === "G" ? 80 : 160;
var regularGames = (c) => c.seasons.reduce((s, l) => s + (l.games || 0), 0);
var allGames = (c) => c.seasons.reduce((s, l) => s + (l.games || 0) + (l.poGames || 0), 0);
function nhlWaiverExempt(c) {
  return currentAgreement(c) && c.seasons.length <= 2 && allGames(c) < gamesLimit(c);
}
function nhlWaiverRequired(c) {
  return currentAgreement(c) && (regularGames(c) >= gamesLimit(c) || c.seasons.length >= (c.pos === "G" ? 6 : 5));
}

// src/lib/nhlCareerLifeA.ts
var L7 = (c) => c;
var clamp24 = (v, lo = 0, hi = 100) => Math.max(lo, Math.min(hi, v));
var r13 = (v) => Math.round(v * 10) / 10;
var r22 = (v) => Math.round(v * 100) / 100;
var mor4 = (c, n2) => {
  const b = c.morale;
  c.morale = clamp24(c.morale + n2);
  return c.morale - b;
};
var fan4 = (c, n2) => {
  const b = c.fanbase;
  c.fanbase = clamp24(c.fanbase + n2);
  return c.fanbase - b;
};
var hp4 = (c, n2) => {
  const b = c.health;
  c.health = clamp24(c.health + n2);
  return c.health - b;
};
var rate4 = (c, n2) => {
  const b = c.ovr;
  c.ovr = Math.max(55, Math.min(c.pot + 1, c.ovr + n2));
  return c.ovr - b;
};
var cash = (c, m) => {
  const l = L7(c);
  l.netWorth = r13((l.netWorth ?? 0) + m);
  if (m > 0) c.earnings = r13(c.earnings + m);
  return r22(Math.abs(m));
};
var heatUp4 = (c, n2) => {
  const l = L7(c);
  l.heat = clamp24((l.heat ?? 0) + n2);
  return l.heat;
};
var flag10 = (c, k, n2 = 1) => {
  const l = L7(c);
  const cur = l.lifeFlags ?? {};
  l.lifeFlags = { ...cur, [k]: (cur[k] ?? 0) + n2 };
};
var buy = (c, item) => {
  const l = L7(c);
  l.purchased = [...l.purchased ?? [], item];
};
