init_careerRetirement();
var L8 = (c) => c;
var clamp25 = (n2, lo, hi) => Math.max(lo, Math.min(hi, n2));
var m1 = (n2) => Math.round(n2 * 10) / 10;
var m2 = (n2) => Math.round(n2 * 100) / 100;
var atEra6 = (c, amount) => m1(nhlEraById(c.eraId).moneyScale * amount);
var payCut = (c, by) => Math.min(c.salary, Math.max(atEra6(c, 1), m1(c.salary - by)));
function addNet(c, amt) {
  const l = L8(c);
  l.netWorth = m2((l.netWorth ?? 0) + amt);
  return l.netWorth;
}
function addDirty2(c, amt) {
  const l = L8(c);
  l.dirtyMoney = m2((l.dirtyMoney ?? 0) + amt);
  return l.dirtyMoney;
}
function addHeat4(c, amt) {
  const l = L8(c);
  l.heat = clamp25((l.heat ?? 0) + amt, 0, 100);
  return l.heat;
}
function flag11(c, key, val = 1) {
  const l = L8(c);
  l.lifeFlags = { ...l.lifeFlags ?? {}, [key]: val };
}
function own7(c, item) {
  const l = L8(c);
  const list = l.purchased ?? [];
  l.purchased = list.includes(item) ? list : [...list, item];
}
function mood(c, d) {
  c.morale = clamp25(c.morale + d, 0, 100);
  return c.morale;
}
function fans(c, d) {
  c.fanbase = clamp25(c.fanbase + d, 0, 100);
  return c.fanbase;
}
function hp5(c, d) {
  c.health = clamp25(c.health + d, 0, 100);
  return c.health;
}
function otherTeam4(c, r) {
  const pool = nhlEraTeamIds(c.eraId).filter((id) => id !== c.team);
  return pool[Math.floor(r() * pool.length)];
}
