    ovr: base,
    pot,
    morale: 70,
    fanbase: stock > 0 && stock <= 10 ? 55 : 32,
    health: entry?.health ?? 100,
    salary: Math.max(0.3, Math.round((stock > 0 && stock <= 10 ? 3.5 : 0.9) * era.moneyScale * 10) / 10),
