function getNhlSpendItem(id) {
  return NHL_SPEND_ITEMS.find((i) => i.id === id);
}
function buyNhlItem(c, itemId) {
  const item = getNhlSpendItem(itemId);
  if (!item) return null;
  const owned = c.purchased ?? [];
  if (item.oneTime && owned.includes(itemId)) return null;
  const net = c.netWorth ?? Math.round(c.earnings * 0.45 * 10) / 10;
  if (item.minNetWorth && net < item.minNetWorth) return null;
  if (item.minFanbase && c.fanbase < item.minFanbase) return null;
  if (item.requiresDirty && (c.dirtyMoney ?? 0) <= 0) return null;
  if (item.cost > net) return null;
  const s = { ...c, purchased: [...owned, itemId] };
  s.netWorth = Math.round((net - item.cost) * 10) / 10;
  if (item.yearly) s.yearlyCosts = Math.round(((s.yearlyCosts ?? 0) + item.yearly) * 100) / 100;
  let log = `Bought ${item.name}.`;
  switch (itemId) {
    case "hometown_court":
      s.fanbase = Math.min(100, s.fanbase + 12);
      log = "You rebuilt the courts you grew up on. The whole neighborhood came out for the reopening.";
      break;
    case "youth_academy_nhl":
      s.fanbase = Math.min(100, s.fanbase + 8);
      log = "Your academy opened with 120 kids on day one.";
      break;
    case "team_stake":
      s.fanbase = Math.min(100, s.fanbase + 10);
      log = "You own a piece of a franchise now. The other owners are still deciding how they feel about that.";
      break;
    case "sleep_nhl":
      s.health = Math.min(100, s.health + 8);
      log = "Turns out it was mostly sleep the whole time. Health +8.";
      break;
    case "biomech_nhl":
      s.ovr = raiseWithinPotential(s.ovr, s.pot, 2);
      log = `They rebuilt how you land and everything got easier. ${ratingRaiseNote(c.ovr, s.ovr, 2)}`;
      break;
    case "psych_nhl":
      s.morale = Math.min(100, s.morale + 8);
      log = "Best hire you ever made and the one you almost skipped. Morale +8.";
      break;
    case "mom_house_nhl":
      s.morale = Math.min(100, s.morale + 15);
      log = "You handed your mother the keys and she did not say a word for a full minute. Morale +15.";
      break;
    case "siblings_nhl":
      s.morale = Math.min(100, s.morale + 10);
      log = "Every sibling, all four years, paid in full. Morale +10.";
      break;
    case "album":
      s.fanbase = Math.min(100, s.fanbase + 10);
      log = "The album has four million streams and the locker room has never let it go. Fanbase +10.";
      break;
    case "signature_shoe":
      s.fanbase = Math.min(100, s.fanbase + 12);
      log = "Your silhouette is on a shoe in every mall in the country. Fanbase +12.";
      break;
    case "foundation_nhl":
      s.fanbase = Math.min(100, s.fanbase + 10);
      log = "The foundation launched with a block party and a scholarship fund. Fanbase +10.";
      break;
    case "hshady_laundromats": {
      const w = Math.min(2, c.dirtyMoney ?? 0);
      s.dirtyMoney = Math.max(0, Math.round(((s.dirtyMoney ?? 0) - 2) * 10) / 10);
      s.netWorth = Math.round((s.netWorth + w) * 10) / 10;
      log = "Two million went in dirty and came out as a very busy laundromat chain.";
      break;
    }
    case "hshady_barbers": {
      const w = Math.min(1.5, c.dirtyMoney ?? 0);
      s.dirtyMoney = Math.max(0, Math.round(((s.dirtyMoney ?? 0) - 1.5) * 10) / 10);
      s.netWorth = Math.round((s.netWorth + w) * 10) / 10;
      log = "Nine chairs, three customers, and a ledger that balances beautifully.";
      break;
    }
    case "hshady_club": {
      const w = Math.min(4, c.dirtyMoney ?? 0);
      s.dirtyMoney = Math.max(0, Math.round(((s.dirtyMoney ?? 0) - 4) * 10) / 10);
      s.netWorth = Math.round((s.netWorth + w) * 10) / 10;
      s.heat = Math.min(100, (s.heat ?? 0) + 3);
      log = "The club opened. Four million cleaned and a line around the block.";
      break;
    }
    case "hshady_fixer":
      s.heat = Math.max(0, (s.heat ?? 0) - 8);
      log = "You have a guy now. Heat -8, and you genuinely do not want to know how.";
      break;
    case "hshady_offshore":
      s.heat = Math.min(100, (s.heat ?? 0) + 6);
      log = "The account is open. An island, a bank, and a form nobody will ever file. Heat +6.";
      break;
    case "shooting_room":
      s.ovr = raiseWithinPotential(s.ovr, s.pot, 1);
      log = `Five hundred pucks a night in your own basement. ${ratingRaiseNote(c.ovr, s.ovr, 1)}`;
      break;
    case "billet_house":
      s.morale = Math.min(100, s.morale + 15);
      log = "You handed the keys to the family that fed you at sixteen. Nobody in that kitchen said anything for a full minute. Morale +15.";
      break;
    case "junior_stake":
      s.fanbase = Math.min(100, s.fanbase + 8);
      log = "You own a piece of the barn you came up in. Fanbase +8.";
      break;
    case "outdoor_rink":
      s.fanbase = Math.min(100, s.fanbase + 10);
      log = "The outdoor rink opened in November. It has not been empty since. Fanbase +10.";
      break;
    case "lake_cabin":
      s.morale = Math.min(100, s.morale + 8);
      log = "No cell service, one dock, June through August. Morale +8.";
      break;
    default:
      break;
  }
  return { state: s, log };
}

// src/lib/nhlCareerPreDraft.ts
var DEV_LEVEL = {
  junior: "Major junior",
  college: "NCAA college hockey",
  europe: "European pro league"
};
function nhlStatLine2(perf, rng, pos3) {
  if (pos3 === "G") {
    const sv = Math.min(0.935, Math.max(0.86, 0.875 + perf / 2e3 + (rng() - 0.5) * 0.01));
    return [
      { label: "SV%", value: sv.toFixed(3).replace(/^0/, "") },
      { label: "GAA", value: Math.max(1.6, 4.2 - perf / 40 + (rng() - 0.5) * 0.4).toFixed(2) }
    ];
  }
  const f = 0.4 + perf / 100;
  const perGame = (base) => Math.round(base * f * (0.75 + rng() * 0.5) / 60 * 100) / 100;
  const g = perGame(pos3 === "D" ? 8 : 24);
  const a = perGame(pos3 === "D" ? 26 : 30);
  return [
    { label: "G/GP", value: g.toFixed(2) },
    { label: "A/GP", value: a.toFixed(2) },
    { label: "PTS/GP", value: (g + a).toFixed(2) }
  ];
}
function nhlPreDraftDescriptor(eraId) {
  const era = nhlEraById(eraId);
  return {
    sport: "nhl",
    eraId: era.id,
    draftYear: era.startYear,
    rounds: 7,
    teamIds: () => nhlEraTeamIds(era.id),
    teamLabel: (id) => nhlTeamLabelOf(id, era.id),
    lottery: null,
    routes: [
      {
        id: "junior",
        label: "Major junior",
        level: "Major junior",
        blurb: "Long season, long bus rides, scouts in every rink. Enter the draft at 18.",
        seasons: 2,
        startAge: 16,
        stockStart: 3
      },
      {
        id: "college",
        label: "US junior, then college",
        level: "US junior hockey",
        blurb: "Two seasons of US junior, enter the draft at 18, then take your college place.",
        seasons: 2,
        startAge: 16,
        stockStart: -2
      },
      {
        id: "europe",
        label: "Europe",
        level: "European junior league",
        blurb: "Two seasons in a European junior league, enter the draft at 18, then develop at home.",
        seasons: 2,
        startAge: 16,
        stockStart: -3
      }
    ],
    showcaseName: "Scouting combine",
    /* The combine is off ice: no skating test. Today's tests are verified
       twice (audit, NHL section); the 2006 test list is not, so that era
       names only the fitness testing and the team interviews. */
    drills: era.id === "now" ? ["Bike test", "Standing long jump", "Pro agility", "Interview day"] : ["Fitness testing", "Interview day"],
    statLine: (perf, rng, pos3) => nhlStatLine2(perf, rng, pos3),
    choices: [
      {
        id: "nhl_tournament",
        title: "The under 18 tournament",
        body: "Your country wants you for the spring tournament. It lands right on top of the playoffs.",
        options: [
          { label: "Go to the tournament", effect: { stock: 4, health: -10 } },
          { label: "Stay with your club", effect: { rating: 1 } }
        ]
      },
      {
        id: "nhl_billet",
        title: "A new billet family",
        body: "Your billet family is moving. The team can find you a new one, or you can room with a teammate.",
        routes: ["junior"],
        options: [
          { label: "New billet family", effect: { health: 10 } },
          { label: "Room with a teammate", effect: { rating: 1, health: -5 } }
        ]
      }
    ],
    postDraft: {
      title: "Development seasons",
      min: 1,
      max: 3,
      levelFor: (_i, _n, routeId) => DEV_LEVEL[routeId] ?? "Major junior"
    },
    undraftedLine: "Nobody calls your name. A club invites you to camp on a tryout."
  };
}

