// src/lib/soccerCareerAppearance.ts
function defaultAppearance() {
  return {
    skinTone: "olive",
    hairstyle: "fade",
    hairColor: "black",
    facialHair: "none",
    celebration: "knee_slide",
    boots: "vortex_strike",
    accessory: "none"
  };
}

// src/lib/usCareerProspect.ts
function createUsCareerProspect(sport, input) {
  const arch = sport.create.archetypes[input.pos].find((a) => a.id === input.archetypeId);
  return { v: 1, ...input, ...sport.prospectRatings(arch, keyedRng(`${input.seed}|ratings`)), state: null };
}

